<script lang="ts">
  import Icon from '../common/Icon.svelte'
  import { Icons } from '../../icons'
  import type { Workflow, WorkflowNodeType } from '../../../features/workflow-builder/types'
  import { createEmptyWorkflow, createNode } from '../../../features/workflow-builder/engine'
  import { getTemplatesByCategory, nodeTemplates, workflowTemplates } from '../../../features/workflow-builder/config'

  let currentWorkflow: Workflow | null = null
  let showPalette = true
  let showExecution = false
  let showWorkflowList = false
  let showTemplates = false
  let searchQuery = ''
  let expandedCategories = new Set(['Triggers', 'Logic', 'Actions'])
  const templatesByCategory = getTemplatesByCategory()

  function createWorkflow(): void { currentWorkflow = createEmptyWorkflow() }
  function addNode(type: WorkflowNodeType, name?: string): void {
    const workflow = currentWorkflow ?? createEmptyWorkflow()
    currentWorkflow = { ...workflow, nodes: [...workflow.nodes, createNode(type, { x: 300, y: 200 }, name)] }
  }
  function toggleCategory(category: string): void {
    expandedCategories = new Set(expandedCategories)
    if (expandedCategories.has(category)) expandedCategories.delete(category)
    else expandedCategories.add(category)
  }
  function loadTemplate(id: string): void {
    const template = workflowTemplates.find((item) => item.id === id)
    if (template) currentWorkflow = { ...JSON.parse(JSON.stringify(template.workflow)), id: `workflow-${Date.now()}` }
    showTemplates = false
  }
</script>

<svelte:head><title>Workflow Builder - Adminex</title></svelte:head>

<div class="space-y-6 animate-fade-in">
  <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4"><div><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl bg-purple-100 dark:bg-purple-900/40 flex items-center justify-center"><Icon icon="solar:code-scan-bold" className="w-5 h-5 text-purple-600 dark:text-purple-400" /></div><div><h1 class="text-2xl font-bold text-gray-900 dark:text-white">Workflow Builder</h1><p class="text-sm text-gray-500 dark:text-gray-400">Visual workflow automation with drag-and-drop</p></div></div></div></div>
  <div class="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 rounded-xl p-6 border border-purple-200 dark:border-purple-800"><h3 class="text-sm font-semibold text-purple-900 dark:text-purple-100 mb-1">Advanced Complex Logic</h3><p class="text-sm text-purple-700 dark:text-purple-300 mb-4">Build complex automation workflows with a visual node-based editor. Connect triggers, conditions, and actions to create powerful automated processes.</p><div class="grid grid-cols-2 md:grid-cols-4 gap-4"><div class="flex items-center gap-2 text-sm text-purple-800 dark:text-purple-200"><Icon icon="solar:box-bold" className="w-4 h-4" />Drag &amp; Drop Nodes</div><div class="flex items-center gap-2 text-sm text-purple-800 dark:text-purple-200"><Icon icon="solar:link-bold" className="w-4 h-4" />Visual Connections</div><div class="flex items-center gap-2 text-sm text-purple-800 dark:text-purple-200"><Icon icon="solar:play-bold" className="w-4 h-4" />Workflow Execution</div><div class="flex items-center gap-2 text-sm text-purple-800 dark:text-purple-200"><Icon icon="solar:check-circle-bold" className="w-4 h-4" />Real-time Validation</div></div></div>

  <div class="flex flex-col h-[calc(100vh-180px)] bg-surface-100 dark:bg-surface-800 rounded-2xl overflow-hidden shadow-lg border border-surface-200 dark:border-surface-700">
    <div class="px-4 py-3 bg-white dark:bg-surface-900 border-b border-surface-200 dark:border-surface-700 flex items-center justify-between"><div class="flex items-center gap-4"><div class="relative"><button type="button" on:click={() => (showWorkflowList = !showWorkflowList)} class="flex items-center gap-2 px-3 py-1.5 bg-surface-100 dark:bg-surface-800 rounded-lg hover:bg-surface-200 dark:hover:bg-surface-700 transition-colors"><Icon icon="solar:document-linear" className="w-4 h-4 text-secondary-500" /><span class="text-sm font-medium text-secondary-700 dark:text-secondary-300 max-w-[150px] truncate">{currentWorkflow?.name || 'Select Workflow'}</span><Icon icon={Icons.chevronDown} className="w-4 h-4 text-secondary-400" /></button>{#if showWorkflowList}<div class="absolute top-full left-0 mt-1 w-64 bg-white dark:bg-surface-900 rounded-xl shadow-xl border border-surface-200 dark:border-surface-700 z-50"><div class="p-2 border-b border-surface-200 dark:border-surface-700"><button type="button" on:click={() => { createWorkflow(); showWorkflowList = false }} class="w-full flex items-center gap-2 px-3 py-2 text-sm font-medium text-primary-600 hover:bg-primary-50 rounded-lg"><Icon icon={Icons.plus} className="w-4 h-4" />New Workflow</button><button type="button" on:click={() => { showTemplates = true; showWorkflowList = false }} class="w-full flex items-center gap-2 px-3 py-2 text-sm font-medium text-secondary-600 hover:bg-surface-100 rounded-lg"><Icon icon={Icons.bookmark} className="w-4 h-4" />From Template</button></div><div class="max-h-64 overflow-y-auto p-2"><p class="text-center text-sm text-secondary-400 py-4">No workflows yet</p></div></div>{/if}</div>{#if currentWorkflow}<input value={currentWorkflow.name} on:input={(event) => (currentWorkflow = currentWorkflow ? { ...currentWorkflow, name: (event.currentTarget as HTMLInputElement).value } : null)} class="px-2 py-1 text-sm font-medium bg-transparent border-b border-transparent hover:border-surface-300 focus:border-primary-500 text-secondary-900 dark:text-white focus:outline-none" />{/if}</div><div class="flex items-center gap-2"><button type="button" on:click={() => (showPalette = !showPalette)} class={`p-2 rounded-lg transition-colors ${showPalette ? 'bg-primary-100 dark:bg-primary-900/30 text-primary-600' : 'text-secondary-500 hover:bg-surface-100'}`} title="Toggle palette"><Icon icon="solar:widget-linear" className="w-5 h-5" /></button><button type="button" on:click={() => (showExecution = !showExecution)} class={`p-2 rounded-lg transition-colors ${showExecution ? 'bg-primary-100 dark:bg-primary-900/30 text-primary-600' : 'text-secondary-500 hover:bg-surface-100'}`} title="Toggle execution panel"><Icon icon="solar:play-circle-linear" className="w-5 h-5" /></button><div class="w-px h-6 bg-surface-200 dark:bg-surface-700"></div><button type="button" class="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-secondary-600 dark:text-secondary-400 hover:bg-surface-100 rounded-lg transition-colors"><Icon icon="solar:check-square-linear" className="w-4 h-4" />Validate</button><button type="button" disabled={!currentWorkflow} class="flex items-center gap-1.5 px-4 py-2 bg-primary-500 hover:bg-primary-600 disabled:bg-primary-300 text-white text-sm font-semibold rounded-lg transition-colors"><Icon icon="solar:play-linear" className="w-4 h-4" />Run</button></div></div>
    <div class="flex-1 flex overflow-hidden">
      {#if showPalette}<div class="w-64 shrink-0"><div class="flex flex-col h-full bg-white dark:bg-surface-900 border-r border-surface-200 dark:border-surface-700"><div class="px-4 py-3 border-b border-surface-200 dark:border-surface-700"><h3 class="text-sm font-semibold text-secondary-900 dark:text-white mb-2">Node Palette</h3><div class="relative"><Icon icon={Icons.search} className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-secondary-400" /><input bind:value={searchQuery} placeholder="Search nodes..." class="w-full pl-8 pr-3 py-1.5 text-sm bg-surface-50 dark:bg-surface-800 border border-surface-200 dark:border-surface-700 rounded-lg focus:ring-2 focus:ring-primary-500" /></div></div><div class="flex-1 overflow-y-auto">{#each Object.entries(templatesByCategory) as [category, templates]}{#if !searchQuery || templates.some((item) => item.label.toLowerCase().includes(searchQuery.toLowerCase()) || item.description.toLowerCase().includes(searchQuery.toLowerCase()))}<div class="border-b border-surface-100 dark:border-surface-800 last:border-0"><button type="button" on:click={() => toggleCategory(category)} class="w-full px-4 py-2.5 flex items-center justify-between hover:bg-surface-50 transition-colors"><span class="flex items-center gap-2"><Icon icon={category === 'Triggers' ? 'solar:play-circle-linear' : category === 'Logic' ? 'solar:branching-paths-up-linear' : category === 'Actions' ? 'solar:bolt-linear' : category === 'Transform' ? 'solar:transformation-linear' : 'solar:clock-circle-linear'} className="w-4 h-4 text-secondary-500" /><span class="text-sm font-medium text-secondary-700 dark:text-secondary-300">{category}</span><span class="text-xs text-secondary-400 bg-surface-100 dark:bg-surface-800 px-1.5 py-0.5 rounded">{templates.length}</span></span><Icon icon={expandedCategories.has(category) ? Icons.chevronUp : Icons.chevronDown} className="w-4 h-4 text-secondary-400" /></button>{#if expandedCategories.has(category)}<div class="px-2 pb-2 space-y-1">{#each templates as template}<button type="button" on:click={() => addNode(template.type, template.label)} class="w-full px-3 py-2 flex items-center gap-2 text-left rounded-lg hover:bg-surface-100 transition-colors group"><div class="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform" style={`background-color:${template.color}15`}><Icon icon={template.icon} className="w-4 h-4" style={`color:${template.color}`} /></div><div class="min-w-0"><p class="text-sm font-medium text-secondary-800 dark:text-secondary-200 truncate">{template.label}</p><p class="text-xs text-secondary-400 truncate">{template.description}</p></div></button>{/each}</div>{/if}</div>{/if}{/each}</div><div class="px-4 py-3 border-t border-surface-200 dark:border-surface-700 bg-surface-50 dark:bg-surface-800/50"><p class="text-xs text-secondary-400">Click a node to add it to the canvas, then connect nodes to build your workflow.</p></div></div></div>{/if}
      <div class="flex-1 relative">{#if currentWorkflow}<div class="p-6 flex flex-wrap gap-4">{#each currentWorkflow.nodes as node}<div class="w-48 bg-white dark:bg-surface-900 rounded-xl border border-surface-200 dark:border-surface-700 p-4"><p class="text-xs uppercase text-primary-500">{node.type}</p><p class="font-semibold mt-2 text-secondary-900 dark:text-white">{node.name}</p></div>{/each}</div>{:else}<div class="flex items-center justify-center h-full bg-surface-100 dark:bg-surface-800"><div class="text-center"><div class="w-16 h-16 mx-auto mb-4 rounded-2xl bg-gradient-to-br from-primary-100 to-accent-100 dark:from-primary-900/30 dark:to-accent-900/30 flex items-center justify-center"><Icon icon="solar:branching-paths-up-linear" className="w-8 h-8 text-primary-500" /></div><h3 class="text-lg font-semibold text-secondary-900 dark:text-white mb-2">No Workflow Selected</h3><p class="text-sm text-secondary-500 mb-4">Create a new workflow or select an existing one to get started.</p><div class="flex items-center justify-center gap-2"><button type="button" on:click={createWorkflow} class="flex items-center gap-2 px-4 py-2 bg-primary-500 hover:bg-primary-600 text-white text-sm font-semibold rounded-lg transition-colors"><Icon icon={Icons.plus} className="w-4 h-4" />New Workflow</button><button type="button" on:click={() => (showTemplates = true)} class="flex items-center gap-2 px-4 py-2 bg-surface-200 dark:bg-surface-700 hover:bg-surface-300 text-secondary-700 dark:text-secondary-300 text-sm font-medium rounded-lg transition-colors"><Icon icon={Icons.bookmark} className="w-4 h-4" />From Template</button></div></div></div>{/if}</div>{#if showExecution}<div class="w-80 shrink-0 bg-white dark:bg-surface-900 border-l border-surface-200 p-4"><h3 class="font-semibold">Execution</h3></div>{/if}
    </div>
  </div>
  {#if showTemplates}<div class="fixed inset-0 z-[1050] flex items-center justify-center p-4"><button type="button" class="absolute inset-0 bg-black/50 backdrop-blur-sm" aria-label="Close templates" on:click={() => (showTemplates = false)}></button><div class="relative bg-white dark:bg-surface-900 rounded-2xl shadow-2xl w-full max-w-2xl max-h-[80vh] overflow-hidden"><div class="px-6 py-4 border-b border-surface-200 flex items-center justify-between"><h3 class="text-lg font-semibold">Workflow Templates</h3><button type="button" on:click={() => (showTemplates = false)} class="p-2"><Icon icon={Icons.close} className="w-5 h-5" /></button></div><div class="p-6 grid gap-3">{#each workflowTemplates as template}<button type="button" on:click={() => loadTemplate(template.id)} class="text-left p-4 rounded-xl border border-surface-200 hover:border-primary-300"><p class="font-semibold">{template.name}</p><p class="text-sm text-secondary-500 mt-1">{template.description}</p></button>{/each}</div></div></div>{/if}
</div>


